+              )
+          )
+          .setGranularity(hasTimestamp ? Granularities.DAY : Granularities.ALL)
+          .build();
+
+      final CacheStrategy<ResultRow, Object, GroupByQuery> strategy =
+          new GroupByQueryQueryToolChest(null).getCacheStrategy(query);
+      final ResultRow result = hasTimestamp
+                               ? ResultRow.of(123L, "#en.wikipedia", null, 10516, 21032, 31548)
+                               : ResultRow.of("#en.wikipedia", null, 10516, 21032, 31548);
+
+      final Object cachedResult = objectMapper.readValue(
+          objectMapper.writeValueAsBytes(strategy.prepareForCache(true).apply(result)),
+          strategy.getCacheObjectClazz()
+      );
+
+      Assert.assertEquals(result, strategy.pullFromCache(true).apply(cachedResult));
+
+      final ResultRow segmentResult = hasTimestamp
+                                      ? ResultRow.of(123L, "#en.wikipedia", null, 10516)
+                                      : ResultRow.of("#en.wikipedia", null, 10516);
