+          objectMapper.writeValueAsBytes(strategy.prepareForSegmentLevelCache().apply(segmentResult)),
+          strategy.getCacheObjectClazz()
+      );
+
+      Assert.assertEquals(segmentResult, strategy.pullFromSegmentLevelCache().apply(cachedSegmentResult));
+    }
+  }
